/* Editorial camera and accessible closer-look commerce, powered by GSAP. */
window.initShowroom=function({hero,scene,camera,motion,paint}){
 const gs=window.gsap,reduced=matchMedia('(prefers-reduced-motion: reduce)');
 const dialog=document.createElement('dialog');dialog.className='showroom-dialog';dialog.setAttribute('aria-labelledby','look-name');document.body.append(dialog);
 let current=null,origin=null,busy=false,closing=false,intro=null,wind=null,visible=true,lastPointer=null;
 const tween=(element,from,to)=>{if(gs&&!reduced.matches)return gs.fromTo(element,from,to);Object.assign(element.style,{opacity:'1',transform:'none'});to.onComplete?.();};
 function ambient(){wind?.kill();wind=null;motion.phase=0;if(gs&&!reduced.matches){wind=gs.to(motion,{phase:Math.PI*2,duration:15,ease:'none',repeat:-1,onUpdate:paint});if(!visible||dialog.open)wind.pause();}paint();}
 function finishIntro(){if(intro?.isActive()){intro.progress(1);intro.kill();}if(gs)gs.set(camera,{clearProps:'transform,opacity'});}
 function enter(){if(!gs||reduced.matches){camera.style.opacity='1';return;}gs.set(camera,{scale:2.15,transformOrigin:'50% 48%',opacity:0});intro=gs.timeline().to(camera,{opacity:1,duration:.25}).to(camera,{scale:1,duration:2.8,ease:'power3.inOut',clearProps:'transform'},0).fromTo(hero.querySelector('.atelier-intro h1'),{opacity:0,y:14},{opacity:1,y:0,duration:1.2,ease:'power2.out'},.75).fromTo(hero.querySelector('.atelier-footer'),{opacity:0,y:12},{opacity:1,y:0,duration:.8},1.8);}
 if(gs&&!reduced.matches)camera.style.opacity='0';
 const first=camera.querySelector('img');Promise.race([first?.decode().catch(()=>{}),new Promise(resolve=>setTimeout(resolve,1500))]).then(enter);
 scene.addEventListener('pointermove',e=>{if(e.pointerType!=='mouse'||dialog.open||hero.classList.contains('dragging')||reduced.matches||!gs)return;const rect=scene.getBoundingClientRect();const pan=(e.clientX-rect.left-rect.width/2)/rect.width*32;gs.to(motion,{pan,duration:1.15,ease:'power2.out',overwrite:'auto',onUpdate:paint});lastPointer=e.clientX;});
 scene.addEventListener('pointerleave',()=>{lastPointer=null;if(gs)gs.to(motion,{pan:0,duration:1.3,ease:'power2.out',overwrite:'auto',onUpdate:paint});});
 scene.addEventListener('pointerdown',finishIntro);
 function angle(view){const angle=view==='back'?180:view==='side'?90:0;const item=dialog.querySelector('.garment-solid');if(gs)gs.to(item,{rotationY:angle,duration:reduced.matches?0:.85,ease:'power3.inOut'});else item.style.transform=`rotateY(${angle}deg)`;dialog.querySelectorAll('[data-look-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lookView===view)));}
 async function open(product,node){if(dialog.open||closing)return;finishIntro();current=product;origin=node;busy=false;const source=node.querySelector('.rig-garment').getBoundingClientRect();wind?.pause();
  dialog.innerHTML=`<div class="showroom-shell"><button type="button" class="showroom-close" aria-label="Close look">Back to rail <span aria-hidden="true">×</span></button><div class="showroom-stage"><div class="detail-garment">${solid(product)}</div><div class="showroom-angles" aria-label="Product views">${['front','side','back'].map(v=>`<button type="button" data-look-view="${v}" aria-pressed="${v==='front'}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div></div><section class="showroom-info"><span class="eyebrow">SHADES / ${product.category}</span><h2 id="look-name">${product.name}</h2><p class="showroom-price">${money(product.price)}</p><p class="showroom-description">${product.description}</p><div class="showroom-color"><span>Color</span><p><i style="background:${product.swatch}" aria-hidden="true"></i>${product.color}</p></div><form id="showroom-add"><fieldset><legend>Choose your size</legend><div class="showroom-sizes">${product.sizes.map(size=>`<label><input type="radio" name="look-size" value="${size}" required><span>${size}</span></label>`).join('')}</div></fieldset><button class="button dark showroom-add" type="submit"><span>Add to bag</span></button><p class="showroom-status" role="status"></p></form><a href="${url(product)}" class="text-link showroom-full-product">View full product details</a><p class="showroom-sample">Sample showroom. No payment is taken.</p></section></div>`;
  dialog.showModal();hero.inert=true;document.documentElement.classList.add('look-is-open');origin.classList.add('detail-origin');
  const preview=dialog.querySelector('.detail-garment'),destination=preview.getBoundingClientRect();const scale=Math.min(1,source.height/destination.height);
  tween(preview,{x:source.x+source.width/2-destination.x-destination.width/2,y:source.y+source.height/2-destination.y-destination.height/2,scale,opacity:1},{x:0,y:0,scale:1,opacity:1,duration:.95,ease:'power3.inOut'});
  tween(dialog.querySelector('.showroom-info'),{x:35,opacity:0},{x:0,opacity:1,duration:.75,delay:.25,ease:'power3.out'});
  dialog.querySelector('.showroom-close').onclick=close;
  dialog.querySelectorAll('[data-look-view]').forEach(b=>b.onclick=()=>angle(b.dataset.lookView));
  dialog.querySelector('#showroom-add').onsubmit=async e=>{e.preventDefault();if(busy)return;const size=new FormData(e.target).get('look-size');if(!product.sizes.includes(size))return;busy=true;dialog.setAttribute('aria-busy','true');const button=e.target.querySelector('button[type=submit]'),status=dialog.querySelector('.showroom-status');button.disabled=true;dialog.querySelector('.showroom-close').disabled=true;button.innerHTML='<span class="showroom-spinner" aria-hidden="true"></span><span>Adding…</span>';status.textContent='Folding your selection…';try{await window.addHeroToBag(product,size,preview);status.innerHTML='Added to your bag. <a href="cart.html">View bag</a>';button.innerHTML='<span>Added to bag</span>';}catch{status.textContent='Your selection could not be added. Please try again.';button.innerHTML='<span>Add to bag</span>';}finally{busy=false;button.disabled=false;dialog.querySelector('.showroom-close').disabled=false;dialog.removeAttribute('aria-busy');}};
 }
 function finishClose(){dialog.close();hero.inert=false;document.documentElement.classList.remove('look-is-open');origin?.classList.remove('detail-origin');origin?.focus({preventScroll:true});origin=null;current=null;closing=false;if(visible)wind?.resume();}
 function close(){if(!dialog.open||busy||closing)return;closing=true;if(gs&&!reduced.matches){gs.killTweensOf(dialog.querySelectorAll('.detail-garment,.showroom-info'));gs.to(dialog.querySelector('.showroom-shell'),{opacity:0,y:10,duration:.25,ease:'power2.in',onComplete:finishClose});}else finishClose();}
 dialog.addEventListener('cancel',e=>{e.preventDefault();close()});dialog.addEventListener('click',e=>{if(e.target===dialog)close()});
 reduced.addEventListener('change',()=>{finishIntro();ambient()});ambient();
 return {open,finishIntro,visibility(value){visible=value;if(value&&!dialog.open)wind?.resume();else wind?.pause();}};
};
